namespace WhatsBiz.Infrastructure.Persistence;
public sealed class FinanceRepository(ApplicationDbContext db, ICurrentUserService currentUser) : IFinanceRepository { private string ConnectionString => db.Database.GetConnectionString() ?? throw new InvalidOperationException("Database connection is unavailable."); private Guid Tenant => currentUser.TenantId ?? throw new UnauthorizedAccessException("A tenant context is required."); private async Task<SqlConnection> Open(CancellationToken token){var c=new SqlConnection(ConnectionString);await c.OpenAsync(token);await using var q=c.CreateCommand();q.CommandText="EXEC sys.sp_set_session_context @key=N'TenantId',@value=@tenant";q.Parameters.AddWithValue("@tenant",Tenant);await q.ExecuteNonQueryAsync(token);return c;} public Task<IReadOnlyCollection<PartyLedgerRow>> CustomerLedger(Guid id, DateTimeOffset? from, DateTimeOffset? to, CancellationToken token) => Ledger("finance.CustomerLedger", "CustomerId", id, from, to, token); public Task<IReadOnlyCollection<PartyLedgerRow>> SupplierLedger(Guid id, DateTimeOffset? from, DateTimeOffset? to, CancellationToken token) => Ledger("finance.SupplierLedger", "SupplierId", id, from, to, token); private async Task<IReadOnlyCollection<PartyLedgerRow>> Ledger(string table, string key, Guid id, DateTimeOffset? from, DateTimeOffset? to, CancellationToken token) { var rows = new List<PartyLedgerRow>(); await using var c=await Open(token); await using var cmd = c.CreateCommand(); cmd.CommandText = $"SELECT l.EntryDate,l.EntryType,l.ReferenceNumber,l.DebitAmount,l.CreditAmount,SUM(l.DebitAmount-l.CreditAmount)OVER(ORDER BY l.EntryDate,l.JournalEntryId ROWS UNBOUNDED PRECEDING)Balance,l.Narration FROM {table} l JOIN finance.JournalEntries j ON j.JournalEntryId=l.JournalEntryId WHERE j.TenantId=@tenant AND l.{key}=@id AND(@from IS NULL OR l.EntryDate>=@from)AND(@to IS NULL OR l.EntryDate<=@to)ORDER BY l.EntryDate,l.JournalEntryId"; cmd.Parameters.AddWithValue("@tenant",Tenant);cmd.Parameters.AddWithValue("@id", id); cmd.Parameters.AddWithValue("@from", from ?? (object)DBNull.Value); cmd.Parameters.AddWithValue("@to", to ?? (object)DBNull.Value); await using var r = await cmd.ExecuteReaderAsync(token); while (await r.ReadAsync(token)) rows.Add(new(r.GetDateTimeOffset(0), r.GetString(1), r.IsDBNull(2) ? null : r.GetString(2), r.GetDecimal(3), r.GetDecimal(4), r.GetDecimal(5), r.IsDBNull(6) ? null : r.GetString(6))); return rows; } public Task<IReadOnlyCollection<BookRow>> CashBook(DateTimeOffset? from, DateTimeOffset? to, CancellationToken token) => Book(false, from, to, token); public Task<IReadOnlyCollection<BookRow>> BankBook(DateTimeOffset? from, DateTimeOffset? to, CancellationToken token) => Book(true, from, to, token); private async Task<IReadOnlyCollection<BookRow>> Book(bool bank, DateTimeOffset? from, DateTimeOffset? to, CancellationToken token) { var rows = new List<BookRow>(); await using var c=await Open(token); await using var cmd = c.CreateCommand(); cmd.CommandText = bank ? "SELECT b.EntryDate,b.EntryType,b.ReferenceNumber,m.ModeName,b.AmountIn,b.AmountOut,SUM(b.AmountIn-b.AmountOut)OVER(ORDER BY b.EntryDate,b.BankBookId),b.Narration FROM finance.BankBook b JOIN finance.JournalEntries j ON j.JournalEntryId=b.JournalEntryId JOIN finance.PaymentModes m ON m.PaymentModeId=b.PaymentModeId WHERE j.TenantId=@tenant AND(@from IS NULL OR b.EntryDate>=@from)AND(@to IS NULL OR b.EntryDate<=@to)ORDER BY b.EntryDate,b.BankBookId" : "SELECT b.EntryDate,b.EntryType,CAST(NULL AS NVARCHAR(100)),CAST('Cash'AS NVARCHAR(100)),b.AmountIn,b.AmountOut,SUM(b.AmountIn-b.AmountOut)OVER(ORDER BY b.EntryDate,b.CashBookId),b.Narration FROM finance.CashBook b JOIN finance.JournalEntries j ON j.JournalEntryId=b.JournalEntryId WHERE j.TenantId=@tenant AND(@from IS NULL OR b.EntryDate>=@from)AND(@to IS NULL OR b.EntryDate<=@to)ORDER BY b.EntryDate,b.CashBookId"; cmd.Parameters.AddWithValue("@tenant",Tenant);cmd.Parameters.AddWithValue("@from", from ?? (object)DBNull.Value); cmd.Parameters.AddWithValue("@to", to ?? (object)DBNull.Value); await using var r = await cmd.ExecuteReaderAsync(token); while (await r.ReadAsync(token)) rows.Add(new(r.GetDateTimeOffset(0), r.GetString(1), r.IsDBNull(2) ? null : r.GetString(2), r.IsDBNull(3) ? null : r.GetString(3), r.GetDecimal(4), r.GetDecimal(5), r.GetDecimal(6), r.IsDBNull(7) ? null : r.GetString(7))); return rows; } public async Task<IReadOnlyCollection<DayBookRow>> DayBook(DateTimeOffset? from, DateTimeOffset? to, CancellationToken token) { var rows = new List<DayBookRow>(); await using var c=await Open(token); await using var cmd = c.CreateCommand(); cmd.CommandText = "SELECT b.EntryDate,b.TransactionType,b.ReferenceNumber,b.DebitTotal,b.CreditTotal,b.Narration FROM finance.DayBook b JOIN finance.JournalEntries j ON j.JournalEntryId=b.JournalEntryId WHERE j.TenantId=@tenant AND(@from IS NULL OR b.EntryDate>=@from)AND(@to IS NULL OR b.EntryDate<=@to)ORDER BY b.EntryDate DESC";cmd.Parameters.AddWithValue("@tenant",Tenant); cmd.Parameters.AddWithValue("@from", from ?? (object)DBNull.Value); cmd.Parameters.AddWithValue("@to", to ?? (object)DBNull.Value); await using var r = await cmd.ExecuteReaderAsync(token); while (await r.ReadAsync(token)) rows.Add(new(r.GetDateTimeOffset(0), r.GetString(1), r.IsDBNull(2) ? null : r.GetString(2), r.GetDecimal(3), r.GetDecimal(4), r.IsDBNull(5) ? null : r.GetString(5))); return rows; } public async Task<(Guid Id, string Number)> Post(string transactionType, string partyType, Guid partyId, string mode, decimal amount, DateTimeOffset date, string? reference, string? narration, string? user, CancellationToken token) { await using var c=await Open(token); await using var cmd = c.CreateCommand(); cmd.CommandText = "finance.PostPartyTransaction"; cmd.CommandType = CommandType.StoredProcedure; foreach (var x in new[] { ("@TenantId",(object?)Tenant),("@TransactionType", transactionType), ("@PartyType", partyType), ("@PartyId", partyId), ("@PaymentMode", mode), ("@Amount", amount), ("@EntryDate", date), ("@ReferenceNumber", reference), ("@Narration", narration), ("@CreatedBy", user) }) cmd.Parameters.AddWithValue(x.Item1, x.Item2 ?? DBNull.Value); try { await using var r = await cmd.ExecuteReaderAsync(token); if (!await r.ReadAsync(token)) throw new InvalidOperationException("Financial posting returned no result."); return (r.GetGuid(0), r.GetString(1)); } catch (SqlException ex) when (ex.Number >= 51300) { throw new BusinessRuleException(ex.Message); } } }
